int main() {
    // Create a UCS-4 input with a dot to trigger multi-label processing
    // The idea: pass a label that when encoded via punycode + additional labels
    // exceeds 63 bytes total output

    // Let's try: a long non-ASCII label that will produce a long punycode output
    // followed by ".a" to add more characters

    // First, let's try a simple test: a single label with many non-ASCII chars
    // that will produce a long punycode output
    uint32_t input[100];
    int len = 0;

    // Add many non-ASCII characters that will expand in punycode
    // Characters like U+3042 (HIRAGANA LETTER A) etc.
    for (int i = 0; i < 20; i++) {
        input[len++] = 0x3042;  // HIRAGANA LETTER A
    }
    // Add a dot to create a second label
    input[len++] = 0x002E;  // '.'
    // Add a simple ASCII label
    input[len++] = 0x0061;  // 'a'

    char output[64];
    memset(output, 'A', sizeof(output));
    output[63] = 0;

    printf("Calling idn2_to_ascii_4i with %d input code points\n", len);
    int rc = idn2_to_ascii_4i(input, len, output, 0);
    printf("rc = %d\n", rc);
    printf("output = %s\n", output);
    printf("output length = %zu\n", strlen(output));

    return 0;
}
EOF
